def replaceNonCoprimes(nums):
    # Helper function to compute gcd
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    # Helper function to compute lcm safely
    def lcm(a, b):
        return a * b // gcd(a, b)

    stack = []
    for num in nums:
        stack.append(num)
        # Continuously merge while the last two elements are non-coprime
        while len(stack) >= 2:
            x = stack[-1]
            y = stack[-2]
            g = gcd(x, y)
            if g == 1:
                break
            # Replace the last two with their lcm
            stack.pop()
            stack[-1] = lcm(y, x)
    return stack
